"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8254],{52549:e=>{e.exports=JSON.parse('{"functions":[{"name":"configureKnife","desc":"Styles a knife accessory in place, overlaying the item\'s config onto\\n`defaultKnife` and backfilling any key the item omits.\\n\\nMesh id, texture id and scale are written onto the handle\'s `SpecialMesh`;\\ncolour and material onto the handle itself. Handle size is only forced when\\nthe accessory is named `Handle` \u2014 prop knives keep their own size so the\\ncharacter does not jitter while moving. Any config key that is not a known\\nknife property is copied onto the accessory as an attribute.","params":[{"name":"knife","desc":"accessory to style; must contain a Handle","lua_type":"Accessory"},{"name":"data","desc":"item config overriding the defaults","lua_type":"ItemTypes.BaseItem?"}],"returns":[],"function_type":"static","source":{"line":68,"path":"src/Server/Features/Shop/ItemProcessor.luau"}},{"name":"setPropKnife","desc":"Attaches the holstered \\"PropKnife\\" accessory to the player\'s character,\\nreplacing any existing one.\\n\\nBuilds an Accessory with a Handle Part and a `WaistCenterAttachment`, then\\nlets `humanoid:AddAccessory` rigid-weld it to the character\'s matching waist\\nattachment. The attachment\'s orientation is derived by inverting the item\'s\\n`propGrip` CFrame and converting to Euler angles, with a 50 degree pitch\\noffset so the blade sits against the hip.\\n\\nThis accessory-building pattern is the model [CosmeticService] follows for\\nits always-on cosmetic.","params":[{"name":"player","desc":"character owner","lua_type":"Player"},{"name":"data","desc":"item config, including `props.propGrip`","lua_type":"ItemTypes.BaseItem?"}],"returns":[],"function_type":"static","source":{"line":130,"path":"src/Server/Features/Shop/ItemProcessor.luau"}},{"name":"equip","desc":"Applies an item\'s visual effect to the player\'s character, dispatching on\\n`item.type`. No-ops unless the player is alive and has a character.\\n\\n- **pets** \u2014 destroys any previously tagged pet, clones the item\'s model and\\n  tethers it to a `PetAttachment` on the character root with an\\n  AlignPosition and AlignOrientation pair, offset by `props.petOffset`.\\n- **melee** \u2014 delegates to [ItemProcessor.setPropKnife].\\n- **trails** / **particles** \u2014 clones the template from\\n  `ServerScriptService.Items` onto the character root if not already\\n  present, then swaps its texture to `props.texture`.","params":[{"name":"player","desc":"character owner","lua_type":"Player"},{"name":"item","desc":"item being equipped","lua_type":"ItemTypes.BaseItem?"}],"returns":[],"function_type":"static","source":{"line":198,"path":"src/Server/Features/Shop/ItemProcessor.luau"}},{"name":"unequip","desc":"Removes an item\'s visual effect, mirroring [ItemProcessor.equip]. No-ops\\nunless the player is alive and has a character.\\n\\nMelee is not removed but reset \u2014 the prop knife is rebuilt from\\n`defaultKnife` so the character keeps a plain blade rather than none.","params":[{"name":"player","desc":"character owner","lua_type":"Player"},{"name":"item","desc":"item being unequipped","lua_type":"ItemTypes.BaseItem?"}],"returns":[],"function_type":"static","source":{"line":303,"path":"src/Server/Features/Shop/ItemProcessor.luau"}}],"properties":[],"types":[],"name":"ItemProcessor","desc":"Legacy equip pipeline: applies the visual side of an equipped item to a\\nplayer\'s character.\\n\\nDispatches on `item.type` to one of four hand-rolled effects \u2014 pets\\n(a cloned model tethered to a `PetAttachment` with AlignPosition and\\nAlignOrientation), melee (a \\"PropKnife\\" accessory whose mesh, texture,\\ncolour and material are overlaid onto `defaultKnife`), trails and particles\\n(a cloned emitter parented to the character root with its texture swapped).\\n\\n:::caution Being phased out\\nThis module is the old pipeline and is on its way out \u2014 see the note in\\n[CosmeticService], which owns cosmetic ownership and all newer\\nequip/apply behaviour and deliberately lives outside this file.\\n[CosmeticService.applyToCharacter] reimplements the accessory-building\\npattern from [ItemProcessor.setPropKnife] rather than calling into it, and\\n[InventoryService.equipItem] / [InventoryService.unequipItem] have already\\nhad their `ItemProcessor` calls commented out. Prefer [CosmeticService] for\\nanything new; nothing should be added here.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":28,"path":"src/Server/Features/Shop/ItemProcessor.luau"}}')}}]);